def _calculate_short_volume_summary(results: List[Dict]) -> Dict:
    """Calculate summary statistics for short volume data"""
    if not results:
        return {}
    short_volume_ratios = [r.get('short_volume_ratio', 0) for r in results]
    short_volumes = [r.get('short_volume', 0) for r in results]
    total_volumes = [r.get('total_volume', 0) for r in results]
    avg_short_volume_ratio = sum(short_volume_ratios) / len(short_volume_ratios) if short_volume_ratios else 0
    total_short_volume = sum(short_volumes)
    total_volume = sum(total_volumes)
    pressure_levels = [r.get('selling_pressure', {}).get('pressure_level', 'Unknown') for r in results]
    pressure_distribution = {}
    for level in pressure_levels:
        pressure_distribution[level] = pressure_distribution.get(level, 0) + 1
    sentiments = [r.get('volume_sentiment', {}).get('sentiment', 'Unknown') for r in results]
    sentiment_distribution = {}
    for sentiment in sentiments:
        sentiment_distribution[sentiment] = sentiment_distribution.get(sentiment, 0) + 1
    venue_usage = {}
    for result in results:
        for venue in ['NYSE', 'Nasdaq Carteret', 'Nasdaq Chicago', 'ADF']:
            volume = result.get(f'{venue.lower().replace(' ', '_')}_short_volume', 0)
            if volume > 0:
                venue_usage[venue] = venue_usage.get(venue, 0) + 1
    return {'total_records': len(results), 'average_short_volume_ratio': round(avg_short_volume_ratio, 2), 'total_short_volume': total_short_volume, 'total_volume': total_volume, 'overall_short_ratio': round(total_short_volume / total_volume * 100 if total_volume > 0 else 0, 2), 'pressure_distribution': pressure_distribution, 'sentiment_distribution': sentiment_distribution, 'venue_usage': venue_usage, 'high_pressure_count': pressure_distribution.get('High', 0) + pressure_distribution.get('Extreme', 0), 'bearish_sentiment_count': sentiment_distribution.get('Bearish', 0) + sentiment_distribution.get('Very Bearish', 0)}

class FederalReserveError:
    """Error handling wrapper for Federal Reserve API responses"""

    def __init__(self, endpoint: str, error: str, status_code: Optional[int]=None):
        self.endpoint = endpoint
        self.error = error
        self.status_code = status_code
        self.timestamp = int(datetime.now().timestamp())

    def to_dict(self) -> Dict[str, Any]:
        return {'success': False, 'error': self.error, 'endpoint': self.endpoint, 'status_code': self.status_code, 'timestamp': self.timestamp}

def __init__(self, endpoint: str, error: str, status_code: Optional[int]=None):
    self.endpoint = endpoint
    self.error = error
    self.status_code = status_code
    self.timestamp = int(datetime.now().timestamp())

class FederalReserveWrapper:
    """Modular Federal Reserve API wrapper with fault tolerance"""

    def __init__(self):
        self.base_url = FED_BASE_URL
        self.ny_fed_url = NY_FED_API_URL
        self.session = requests.Session()
        self.session.headers.update({'User-Agent': 'Fincept-Terminal/1.0'})

    def _make_request(self, url: str, params: Optional[Dict]=None, timeout: int=30) -> Dict[str, Any]:
        """Centralized request handler with comprehensive error handling"""
        try:
            response = self.session.get(url, params=params, timeout=timeout)
            response.raise_for_status()
            content_type = response.headers.get('content-type', '')
            if 'json' in content_type.lower():
                return {'success': True, 'data': response.json(), 'format': 'json'}
            else:
                return {'success': True, 'data': response.content, 'format': 'binary'}
        except requests.exceptions.Timeout:
            return {'error': 'Request timeout', 'timeout': True, 'status_code': None}
        except requests.exceptions.ConnectionError:
            return {'error': 'Connection error', 'connection_error': True, 'status_code': None}
        except requests.exceptions.HTTPError as e:
            if response.status_code == 404:
                return {'error': 'Data not found', 'not_found': True, 'status_code': response.status_code}
            else:
                return {'error': f'HTTP error: {e}', 'http_error': True, 'status_code': response.status_code}
        except requests.exceptions.RequestException as e:
            return {'error': f'Request error: {e}', 'request_error': True, 'status_code': None}
