def get_financials(symbol):
    """Fetch financial statements for a symbol"""
    try:
        ticker = yf.Ticker(symbol)
        income_stmt = ticker.financials
        balance_sheet = ticker.balance_sheet
        cash_flow = ticker.cashflow

        def dataframe_to_dict(df):
            """Convert pandas DataFrame to dict with cleaned values"""
            if df is None or df.empty:
                return {}
            result = {}
            for col in df.columns:
                result[str(col)] = {}
                for idx in df.index:
                    value = df.loc[idx, col]
                    if pd.notna(value):
                        result[str(col)][str(idx)] = float(value) if isinstance(value, (int, float)) else str(value)
            return result
        financials_data = {'symbol': symbol, 'income_statement': dataframe_to_dict(income_stmt), 'balance_sheet': dataframe_to_dict(balance_sheet), 'cash_flow': dataframe_to_dict(cash_flow), 'timestamp': int(datetime.now().timestamp())}
        return financials_data
    except Exception as e:
        return {'error': str(e), 'symbol': symbol}

