    def get_education_overview(self, country_codes: List[str]=None, start_year: int=None, end_year: int=None) -> Dict[str, Any]:
        """Get comprehensive education data overview for countries"""
        try:
            education_indicators = ['ROFST.1', 'NERA.1', 'CR.1', 'SE.XPD.TOTL.GD.ZS', 'UIS.LIT.AG25T64', 'STABBRV.2', 'ENRL.TCHL.ADV.ZS', 'SCH.PRM', 'EDUDATA.NY']
            result = self.get_indicator_data(indicators=education_indicators, geo_units=country_codes or [], start_year=start_year, end_year=end_year, indicator_metadata=True, footnotes=True)
            if result.get('success'):
                result['overview_type'] = 'education_overview'
                result['indicators_count'] = len(education_indicators)
                if country_codes:
                    result['countries'] = country_codes
            return result
        except Exception as e:
            return UISError('get_education_overview', str(e)).to_dict()

