    """CLI interface for UNESCO UIS Data Fetcher"""
    if len(sys.argv) < 2:
        print(json.dumps({'error': 'Usage: python unesco_data.py <command> <args>', 'available_commands': ['indicator_data [indicators...] [geo_units...] [options]', 'export_indicator_data <format> [indicators...] [geo_units...] [options]', 'list_geo_units [version]', 'export_geo_units <format> [version]', 'list_indicators [options]', 'export_indicators <format> [options]', 'get_default_version', 'list_versions', 'education_overview [country_codes...] [start_year] [end_year]', 'global_trends <indicator_code> [start_year] [end_year]', 'country_comparison <indicator_code> <country_codes...> [start_year] [end_year]', 'search_by_theme <theme> [limit]', 'regional_data <region_id> [indicators...] [start_year] [end_year]', 'sti_data [country_codes...] [start_year] [end_year]', 'culture_data [country_codes...] [start_year] [end_year]', 'export_country_dataset <country_code> <format> [include_metadata]'], 'themes': ['EDUCATION', 'SCIENCE_TECHNOLOGY_INNOVATION', 'CULTURE', 'DEMOGRAPHIC_SOCIOECONOMIC'], 'formats': ['csv', 'excel', 'json']}))
