def search_bls_series(self, query: str, category: str='cpi', include_extras: bool=False, include_code_map: bool=False) -> Dict[str, Any]:
    """Search for BLS series by category and query"""
    try:
        if category not in SURVEY_CATEGORIES:
            available_categories = ', '.join(SURVEY_CATEGORY_NAMES.keys())
            return BLSError('bls_search', f'Invalid category. Available: {available_categories}').to_dict()
        cache_key = f'{category}_series'
        series_df = self._get_cached_data(cache_key)
        if series_df is None:
            series_df = self._get_local_category_data(category)
            if series_df is None:
                return BLSError('bls_search', f"Series data for category '{category}' not available locally").to_dict()
            self._set_cache_data(cache_key, series_df)
        if series_df.empty:
            return BLSError('bls_search', f"No series data found for category '{category}'").to_dict()
        if not query.strip():
            results_df = series_df
        else:
            search_terms = [term.strip() for term in query.split(';')]
            combined_mask = pd.Series([True] * len(series_df))
            for term in search_terms:
                term_mask = series_df.apply(lambda row, term=term: row.astype(str).str.contains(term, case=False, regex=False, na=False)).any(axis=1)
                combined_mask &= term_mask
            results_df = series_df[combined_mask]
        if results_df.empty:
            return BLSError('bls_search', f"No results found for query: '{query}' in category '{category}'").to_dict()
        if include_extras:
            results = results_df.to_dict('records')
        else:
            essential_cols = ['series_id', 'series_title', 'survey_name']
            available_cols = [col for col in essential_cols if col in results_df.columns]
            results = results_df[available_cols].to_dict('records')
        metadata = {}
        if include_code_map:
            metadata = self._get_local_code_map(category)
        return {'success': True, 'data': {'query': query, 'category': category, 'results': results, 'metadata': metadata if metadata else None}}
    except Exception as e:
        return BLSError('bls_search', str(e)).to_dict()

def get_survey_categories(self) -> Dict[str, Any]:
    """Get available survey categories"""
    try:
        categories_info = []
        for key, name in SURVEY_CATEGORY_NAMES.items():
            categories_info.append({'category_code': key, 'category_name': name, 'survey_codes': SURVEY_CATEGORIES[key]})
        return {'success': True, 'data': {'categories': categories_info, 'total_categories': len(categories_info)}}
    except Exception as e:
        return BLSError('get_survey_categories', str(e)).to_dict()

class FMPError:
    """Custom error class for FMP API errors"""

    def __init__(self, endpoint: str, error: str, status_code: Optional[int]=None):
        self.endpoint = endpoint
        self.error = error
        self.status_code = status_code
        self.timestamp = int(datetime.now().timestamp())

    def to_dict(self) -> Dict[str, Any]:
        return {'endpoint': self.endpoint, 'error': self.error, 'status_code': self.status_code, 'timestamp': self.timestamp, 'type': 'FMPError'}

def __init__(self, endpoint: str, error: str, status_code: Optional[int]=None):
    self.endpoint = endpoint
    self.error = error
    self.status_code = status_code
    self.timestamp = int(datetime.now().timestamp())

class FMPDataWrapper:
    """Modular FMP data wrapper with fault-tolerant endpoints"""

    def __init__(self, api_key: Optional[str]=None):
        self.base_url = 'https://financialmodelingprep.com/api/v3'
        self.api_key = api_key or os.environ.get('FMP_API_KEY', '')
        self.session = requests.Session()
        self.session.headers.update({'User-Agent': 'Fincept-Terminal/1.0'})
        self.default_limit = 10
        self.interval_map = {'1m': '1min', '5m': '5min', '15m': '15min', '30m': '30min', '1h': '1hour', '4h': '4hour', '1d': 'day'}
        self.period_map = {'annual': 'annual', 'quarter': 'quarter', 'ttm': 'ttm'}
        self.statement_periods = ['annual', 'quarter']

    def _make_request(self, url: str) -> Dict[str, Any]:
        """Make HTTP request with error handling"""
        try:
            response = self.session.get(url, timeout=30)
            response.raise_for_status()
            data = response.json()
            if isinstance(data, dict):
                error_message = data.get('Error Message', data.get('error'))
                if error_message:
                    if any((keyword in error_message.lower() for keyword in ['upgrade', 'subscription', 'exclusive', 'unauthorized'])):
                        raise Exception(f'API Access Error: {error_message}. This feature may require a premium subscription.')
                    else:
                        raise Exception(f'FMP API Error: {error_message}')
            return data
        except requests.exceptions.RequestException as e:
            raise Exception(f'HTTP request failed: {str(e)}')
        except json.JSONDecodeError as e:
            raise Exception(f'JSON decode error: {str(e)}')

    def _build_url(self, endpoint: str, params: Dict[str, Any]=None) -> str:
        """Build API URL with parameters"""
        url = f'{self.base_url}/{endpoint}?apikey={self.api_key}'
        if params:
            filtered_params = {k: v for k, v in params.items() if v is not None}
            for key, value in filtered_params.items():
                if key not in ['symbol']:
                    url += f'&{key}={value}'
        return url

    def get_equity_quote(self, symbols: str) -> Dict[str, Any]:
        """Get real-time stock quotes for multiple symbols"""
        try:
            if not symbols:
                return {'error': FMPError('equity_quote', 'Symbols parameter is required').to_dict()}
            symbol_list = [s.strip() for s in symbols.split(',')]
            results = []
            for symbol in symbol_list:
                try:
                    url = self._build_url(f'quote/{symbol}')
                    data = self._make_request(url)
                    if isinstance(data, list) and len(data) > 0:
                        results.extend(data)
                    elif isinstance(data, dict):
                        results.append(data)
                except Exception as e:
                    continue
            if not results:
                return {'error': FMPError('equity_quote', f'No data found for symbols: {symbols}').to_dict()}
            return {'success': True, 'data': results, 'parameters': {'symbols': symbols}}
        except Exception as e:
            return {'error': FMPError('equity_quote', str(e)).to_dict()}

    def get_company_profile(self, symbol: str) -> Dict[str, Any]:
        """Get company profile and basic information"""
        try:
            if not symbol:
                return {'error': FMPError('company_profile', 'Symbol parameter is required').to_dict()}
            url = self._build_url(f'profile/{symbol}')
            data = self._make_request(url)
            if not data:
                return {'error': FMPError('company_profile', f'No data found for symbol: {symbol}').to_dict()}
            if isinstance(data, list):
                data = data[0] if data else {}
            return {'success': True, 'data': data, 'parameters': {'symbol': symbol}}
        except Exception as e:
            return {'error': FMPError('company_profile', str(e)).to_dict()}

    def get_historical_prices(self, symbol: str, start_date: Optional[str]=None, end_date: Optional[str]=None, interval: str='1d') -> Dict[str, Any]:
        """Get historical price data for a symbol"""
        try:
            if not symbol:
                return {'error': FMPError('historical_prices', 'Symbol parameter is required').to_dict()}
            if not end_date:
                end_date = datetime.now().strftime('%Y-%m-%d')
            if not start_date:
                start_date = (datetime.now() - timedelta(days=365)).strftime('%Y-%m-%d')
            fmp_interval = self.interval_map.get(interval, 'day')
            params = {'from': start_date, 'to': end_date}
            if fmp_interval == 'day':
                url = self._build_url(f'historical-price-full/{symbol}', params)
                data = self._make_request(url)
                historical_data = data.get('historical', []) if isinstance(data, dict) else []
            else:
                url = self._build_url(f'historical-chart/{fmp_interval}/{symbol}', params)
                historical_data = self._make_request(url)
                if not isinstance(historical_data, list):
                    historical_data = []
            if not historical_data:
                return {'error': FMPError('historical_prices', f'No historical data found for symbol: {symbol}').to_dict()}
            return {'success': True, 'data': historical_data, 'parameters': {'symbol': symbol, 'start_date': start_date, 'end_date': end_date, 'interval': interval}}
        except Exception as e:
            return {'error': FMPError('historical_prices', str(e)).to_dict()}

