def main():
    if len(sys.argv) < 2:
        print(json.dumps({'success': False, 'error': 'Usage: python oecd_data.py <command> <args>', 'available_commands': ['gdp_real [countries] [frequency] [start_date] [end_date]', 'cpi [countries] [expenditure] [frequency] [units] [harmonized] [start_date] [end_date]', 'gdp_forecast [countries] [start_date] [end_date]', 'unemployment [countries] [frequency] [start_date] [end_date]', 'interest_rates [countries] [frequency] [start_date] [end_date]', 'trade_balance [countries] [frequency] [start_date] [end_date]', 'economic_summary [country] [start_date] [end_date]', 'country_list'], 'examples': ['python oecd_data.py gdp_real united_states quarter 2020-01-01 2024-12-31', 'python oecd_data.py cpi united_states total monthly index false 2020-01-01 2024-12-31', 'python oecd_data.py unemployment united_states quarter 2020-01-01 2024-12-31', 'python oecd_data.py country_list'], 'notes': ['No API key required - OECD data is publicly available', "Countries: Use country names like 'united_states', 'germany', 'japan' or ISO codes", "Frequency: 'monthly', 'quarter', 'annual' (varies by endpoint)", 'Date format: YYYY-MM-DD', 'The API supports both SDMX v1 and v2 endpoints with automatic fallback']}))
        sys.exit(1)
    command = sys.argv[1]
    wrapper = OECDWrapper()
    try:
        if command == 'gdp_real':
            countries = sys.argv[2] if len(sys.argv) > 2 else 'united_states'
            frequency = sys.argv[3] if len(sys.argv) > 3 else 'quarter'
            start_date = sys.argv[4] if len(sys.argv) > 4 else None
            end_date = sys.argv[5] if len(sys.argv) > 5 else None
            result = wrapper.get_gdp_real(countries=countries, frequency=frequency, start_date=start_date, end_date=end_date)
            print(json.dumps(result, indent=2))
        elif command == 'cpi':
            countries = sys.argv[2] if len(sys.argv) > 2 else 'united_states'
            expenditure = sys.argv[3] if len(sys.argv) > 3 else 'total'
            frequency = sys.argv[4] if len(sys.argv) > 4 else 'monthly'
            units = sys.argv[5] if len(sys.argv) > 5 else 'index'
            harmonized = sys.argv[6].lower() == 'true' if len(sys.argv) > 6 else False
            start_date = sys.argv[7] if len(sys.argv) > 7 else None
            end_date = sys.argv[8] if len(sys.argv) > 8 else None
            result = wrapper.get_consumer_price_index(countries=countries, expenditure=expenditure, frequency=frequency, units=units, harmonized=harmonized, start_date=start_date, end_date=end_date)
            print(json.dumps(result, indent=2))
        elif command == 'gdp_forecast':
            countries = sys.argv[2] if len(sys.argv) > 2 else 'united_states'
            start_date = sys.argv[3] if len(sys.argv) > 3 else None
            end_date = sys.argv[4] if len(sys.argv) > 4 else None
            result = wrapper.get_gdp_forecast(countries=countries, start_date=start_date, end_date=end_date)
            print(json.dumps(result, indent=2))
        elif command == 'unemployment':
            countries = sys.argv[2] if len(sys.argv) > 2 else 'united_states'
            frequency = sys.argv[3] if len(sys.argv) > 3 else 'quarter'
            start_date = sys.argv[4] if len(sys.argv) > 4 else None
            end_date = sys.argv[5] if len(sys.argv) > 5 else None
            result = wrapper.get_unemployment(countries=countries, frequency=frequency, start_date=start_date, end_date=end_date)
            print(json.dumps(result, indent=2))
        elif command == 'economic_summary':
            country = sys.argv[2] if len(sys.argv) > 2 else 'united_states'
            start_date = sys.argv[3] if len(sys.argv) > 3 else None
            end_date = sys.argv[4] if len(sys.argv) > 4 else None
            result = wrapper.get_economic_summary(country=country, start_date=start_date, end_date=end_date)
            print(json.dumps(result, indent=2))
        elif command == 'interest_rates':
            countries = sys.argv[2] if len(sys.argv) > 2 else 'united_states'
            frequency = sys.argv[3] if len(sys.argv) > 3 else 'monthly'
            start_date = sys.argv[4] if len(sys.argv) > 4 else None
            end_date = sys.argv[5] if len(sys.argv) > 5 else None
            result = wrapper.get_interest_rates(countries=countries, frequency=frequency, start_date=start_date, end_date=end_date)
            print(json.dumps(result, indent=2))
        elif command == 'trade_balance':
            countries = sys.argv[2] if len(sys.argv) > 2 else 'united_states'
            frequency = sys.argv[3] if len(sys.argv) > 3 else 'quarter'
            start_date = sys.argv[4] if len(sys.argv) > 4 else None
            end_date = sys.argv[5] if len(sys.argv) > 5 else None
            result = wrapper.get_trade_balance(countries=countries, frequency=frequency, start_date=start_date, end_date=end_date)
            print(json.dumps(result, indent=2))
        elif command == 'country_list':
            result = wrapper.get_country_list()
            print(json.dumps(result, indent=2))
        else:
            print(json.dumps({'success': False, 'error': f'Unknown command: {command}', 'available_commands': ['gdp_real [countries] [frequency] [start_date] [end_date]', 'cpi [countries] [expenditure] [frequency] [units] [harmonized] [start_date] [end_date]', 'gdp_forecast [countries] [start_date] [end_date]', 'unemployment [countries] [frequency] [start_date] [end_date]', 'interest_rates [countries] [frequency] [start_date] [end_date]', 'trade_balance [countries] [frequency] [start_date] [end_date]', 'economic_summary [country] [start_date] [end_date]', 'country_list']}))
            sys.exit(1)
    except KeyboardInterrupt:
        print(json.dumps({'success': False, 'error': 'Operation cancelled by user'}))
        sys.exit(1)
    except Exception as e:
        print(json.dumps({'success': False, 'error': f'Unexpected error: {str(e)}'}))
        sys.exit(1)

def test_connection() -> Dict[str, Any]:
    """Test API connection with a simple call."""
    return _make_request('credit-ratings')

def get_credit_ratings(country: str=None) -> Dict[str, Any]:
    """1. Get sovereign credit ratings for a specific country or all countries."""
    if country:
        endpoint = f'credit-ratings/country/{country}'
    else:
        endpoint = 'credit-ratings'
    data = _make_request(endpoint)
    if data and 'error' not in data and isinstance(data, list):
        return {'data': data, 'count': len(data), 'source': 'Trading Economics', 'timestamp': datetime.now().isoformat()}
    return data

