def main():
    if len(sys.argv) < 2:
        print(json.dumps({'success': False, 'error': 'Usage: python congress_gov_data.py <command> <args>', 'available_commands': ['congress_bills [congress] [bill_type] [start_date] [end_date] [limit] [offset] [sort_by] [get_all]', 'bill_info <bill_url>', 'bill_text <bill_url>', 'download_text <text_url>', 'comprehensive <bill_url>', 'summary [congress] [limit]'], 'note': 'Requires CONGRESS_GOV_API_KEY environment variable'}))
        sys.exit(1)
    command = sys.argv[1]
    wrapper = CongressGovWrapper()
    try:
        if command == 'congress_bills':
            congress = int(sys.argv[2]) if len(sys.argv) > 2 and sys.argv[2] else None
            bill_type = sys.argv[3] if len(sys.argv) > 3 else None
            start_date = sys.argv[4] if len(sys.argv) > 4 else None
            end_date = sys.argv[5] if len(sys.argv) > 5 else None
            limit = int(sys.argv[6]) if len(sys.argv) > 6 and sys.argv[6] else None
            offset = int(sys.argv[7]) if len(sys.argv) > 7 and sys.argv[7] else 0
            sort_by = sys.argv[8] if len(sys.argv) > 8 else 'desc'
            get_all = sys.argv[9].lower() == 'true' if len(sys.argv) > 9 else False
            result = wrapper.get_congress_bills(congress=congress, bill_type=bill_type, start_date=start_date, end_date=end_date, limit=limit, offset=offset, sort_by=sort_by, get_all=get_all)
            print(json.dumps(result, indent=2))
        elif command == 'bill_info':
            if len(sys.argv) < 3:
                print(json.dumps({'success': False, 'error': 'Usage: python congress_gov_data.py bill_info <bill_url>'}))
                sys.exit(1)
            bill_url = sys.argv[2]
            result = wrapper.get_bill_info(bill_url)
            print(json.dumps(result, indent=2))
        elif command == 'bill_text':
            if len(sys.argv) < 3:
                print(json.dumps({'success': False, 'error': 'Usage: python congress_gov_data.py bill_text <bill_url>'}))
                sys.exit(1)
            bill_url = sys.argv[2]
            result = wrapper.get_bill_text(bill_url)
            print(json.dumps(result, indent=2))
        elif command == 'download_text':
            if len(sys.argv) < 3:
                print(json.dumps({'success': False, 'error': 'Usage: python congress_gov_data.py download_text <text_url>'}))
                sys.exit(1)
            text_url = sys.argv[2]
            result = wrapper.download_bill_text(text_url)
            print(json.dumps(result, indent=2))
        elif command == 'comprehensive':
            if len(sys.argv) < 3:
                print(json.dumps({'success': False, 'error': 'Usage: python congress_gov_data.py comprehensive <bill_url>'}))
                sys.exit(1)
            bill_url = sys.argv[2]
            result = wrapper.get_comprehensive_bill_data(bill_url)
            print(json.dumps(result, indent=2))
        elif command == 'summary':
            congress = int(sys.argv[2]) if len(sys.argv) > 2 and sys.argv[2] else None
            limit = int(sys.argv[3]) if len(sys.argv) > 3 and sys.argv[3] else 50
            result = wrapper.get_bill_summary_by_congress(congress=congress, limit=limit)
            print(json.dumps(result, indent=2))
        else:
            print(json.dumps({'success': False, 'error': f'Unknown command: {command}', 'available_commands': ['congress_bills [congress] [bill_type] [start_date] [end_date] [limit] [offset] [sort_by] [get_all]', 'bill_info <bill_url>', 'bill_text <bill_url>', 'download_text <text_url>', 'comprehensive <bill_url>', 'summary [congress] [limit]']}))
            sys.exit(1)
    except KeyboardInterrupt:
        print(json.dumps({'success': False, 'error': 'Operation cancelled by user'}))
        sys.exit(1)
    except Exception as e:
        print(json.dumps({'success': False, 'error': f'Unexpected error: {str(e)}'}))
        sys.exit(1)

def get_organization_details(organization_id: str) -> Dict[str, Any]:
    """
    Get detailed information about a specific organization

    Args:
        organization_id: The unique ID of the organization

    Returns:
        JSON response with organization details
    """
    try:
        params = {'id': organization_id}
        result = _make_request('organization_show', params)
        if result['error']:
            return result
        org_data = result.get('data', {})
        enhanced_org = {'id': org_data.get('id'), 'name': org_data.get('name'), 'title': org_data.get('title'), 'description': org_data.get('description'), 'image_url': org_data.get('image_display_url'), 'created': org_data.get('created'), 'num_datasets': org_data.get('package_count', 0), 'users': org_data.get('users', [])}
        result['data'] = enhanced_org
        result['metadata']['organization_id'] = organization_id
        result['metadata']['description'] = f'Details for organization {organization_id}'
        return result
    except Exception as e:
        return {'data': {}, 'metadata': {}, 'error': f'Error fetching organization details: {str(e)}'}

def get_datasets_by_organization(organization_id: str, rows: int=100) -> Dict[str, Any]:
    """
    Get all datasets published by a specific organization

    Args:
        organization_id: The unique ID of the organization
        rows: Number of datasets to return (default: 100)

    Returns:
        JSON response with dataset list
    """
    try:
        query = f'owner_org:{organization_id}'
        params = {'q': query, 'rows': rows}
        result = _make_request('package_search', params)
        if result['error']:
            return result
        search_data = result.get('data', {})
        datasets = search_data.get('results', [])
        enhanced_data = []
        for dataset in datasets:
            enhanced_dataset = {'id': dataset.get('id'), 'name': dataset.get('name'), 'title': dataset.get('title'), 'notes': dataset.get('notes', ''), 'organization_id': organization_id, 'metadata_created': dataset.get('metadata_created'), 'metadata_modified': dataset.get('metadata_modified'), 'state': dataset.get('state'), 'num_resources': len(dataset.get('resources', [])), 'tags': [tag.get('display_name') for tag in dataset.get('tags', [])]}
            enhanced_data.append(enhanced_dataset)
        result['data'] = enhanced_data
        result['metadata']['organization_id'] = organization_id
        result['metadata']['total_count'] = search_data.get('count', 0)
        result['metadata']['returned_count'] = len(enhanced_data)
        result['metadata']['description'] = f'Datasets for organization {organization_id}'
        return result
    except Exception as e:
        return {'data': [], 'metadata': {}, 'error': f'Error fetching datasets: {str(e)}'}

