def _format_timestamp_fast(self, created_at: str) -> str:
    """PERFORMANCE: Fast timestamp formatting"""
    try:
        if not created_at:
            return 'Recent'
        if created_at.endswith('Z'):
            dt = datetime.fromisoformat(created_at.replace('Z', '+00:00'))
        else:
            dt = datetime.fromisoformat(created_at)
        return dt.strftime('%m/%d %H:%M')
    except Exception:
        return 'Recent'

def generate_report_html(metrics: PortfolioMetrics, equity_curve: pd.Series, trades: pd.DataFrame) -> str:
    """Generate HTML report from results"""
    html = f'\n    <!DOCTYPE html>\n    <html>\n    <head>\n        <title>Strategy Report</title>\n        <style>\n            body {{ font-family: Arial, sans-serif; margin: 20px; }}\n            h1 {{ color: #2e7d32; }}\n            table {{ border-collapse: collapse; width: 100%; }}\n            th, td {{ border: 1px solid #ddd; padding: 8px; text-align: left; }}\n            th {{ background-color: #4caf50; color: white; }}\n            .positive {{ color: green; }}\n            .negative {{ color: red; }}\n        </style>\n    </head>\n    <body>\n        <h1>Trading Strategy Performance Report</h1>\n        \n        <h2>Key Metrics</h2>\n        <table>\n            <tr><th>Metric</th><th>Value</th></tr>\n            <tr><td>Total Return</td><td class="{('positive' if metrics.total_return > 0 else 'negative')}">{metrics.total_return:.2f}%</td></tr>\n            <tr><td>Sharpe Ratio</td><td>{metrics.sharpe_ratio:.2f}</td></tr>\n            <tr><td>Max Drawdown</td><td class="negative">{metrics.max_drawdown:.2f}%</td></tr>\n            <tr><td>Win Rate</td><td>{metrics.win_rate:.1f}%</td></tr>\n            <tr><td>Total Trades</td><td>{metrics.total_trades}</td></tr>\n        </table>\n        \n        <h2>Trade Analysis</h2>\n        <p>Generated on {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}</p>\n    </body>\n    </html>\n    '
    return html

class SettingsManager:
    """Settings Manager for API keys and provider configurations"""

    def __init__(self):
        self.config_dir = self._get_config_directory()
        self.config_dir.mkdir(parents=True, exist_ok=True)
        self.settings_file = self.config_dir / 'provider_settings.json'
        self.load_settings()

    def _get_config_directory(self) -> Path:
        """Get config directory - uses .fincept folder"""
        config_dir = Path.home() / '.fincept' / 'settings'
        return config_dir

    def load_settings(self) -> Dict[str, Any]:
        """Load settings from file"""
        try:
            if self.settings_file.exists():
                with open(self.settings_file, 'r', encoding='utf-8') as f:
                    self.settings = json.load(f)
                info(f'Settings loaded from: {self.settings_file}', module='SettingsManager')
            else:
                self.settings = self._get_default_settings()
                self.save_settings()
                info(f'Default settings created at: {self.settings_file}', module='SettingsManager')
        except Exception as e:
            error(f'Error loading settings: {str(e)}', module='SettingsManager')
            self.settings = self._get_default_settings()
        return self.settings

    def _get_default_settings(self) -> Dict[str, Any]:
        """Get default settings structure"""
        return {'providers': {'alpha_vantage_data': {'api_key': '', 'rate_limit': 5, 'enabled': False, 'last_verified': None}, 'yahoo_finance': {'enabled': True, 'extended_hours': False, 'include_events': True, 'last_verified': None}, 'fincept_api': {'api_key': '', 'endpoint': 'https://api.fincept.com', 'real_time': True, 'enabled': False, 'last_verified': None}}, 'preferences': {'default_provider': 'yfinance', 'cache_enabled': True, 'cache_duration': 300, 'auto_verify': True}, 'created_at': datetime.now().isoformat(), 'last_modified': datetime.now().isoformat()}

    def save_settings(self) -> bool:
        """Save settings to file"""
        try:
            self.config_dir.mkdir(parents=True, exist_ok=True)
            self.settings['last_modified'] = datetime.now().isoformat()
            with open(self.settings_file, 'w', encoding='utf-8') as f:
                json.dump(self.settings, f, indent=2)
            info(f'Settings saved to: {self.settings_file}', module='SettingsManager')
            return True
        except Exception as e:
            error(f'Error saving settings: {str(e)}', module='SettingsManager')
            return False

    def get_provider_config(self, provider_name: str) -> Dict[str, Any]:
        """Get configuration for a specific provider"""
        return self.settings.get('providers', {}).get(provider_name, {})

    def update_provider_config(self, provider_name: str, config: Dict[str, Any]) -> bool:
        """Update configuration for a specific provider"""
        try:
            if 'providers' not in self.settings:
                self.settings['providers'] = {}
            if provider_name not in self.settings['providers']:
                self.settings['providers'][provider_name] = {}
            self.settings['providers'][provider_name].update(config)
            return self.save_settings()
        except Exception as e:
            error(f'Error updating provider config: {str(e)}', module='SettingsManager')
            return False

    def get_api_key(self, provider_name: str) -> str:
        """Get API key for a provider"""
        return self.get_provider_config(provider_name).get('api_key', '')

    def set_api_key(self, provider_name: str, api_key: str) -> bool:
        """Set API key for a provider"""
        return self.update_provider_config(provider_name, {'api_key': api_key})

    def is_provider_enabled(self, provider_name: str) -> bool:
        """Check if a provider is enabled"""
        return self.get_provider_config(provider_name).get('enabled', False)

    def enable_provider(self, provider_name: str, enabled: bool=True) -> bool:
        """Enable or disable a provider"""
        return self.update_provider_config(provider_name, {'enabled': enabled})

def _get_default_settings(self) -> Dict[str, Any]:
    """Get default settings structure"""
    return {'providers': {'alpha_vantage_data': {'api_key': '', 'rate_limit': 5, 'enabled': False, 'last_verified': None}, 'yahoo_finance': {'enabled': True, 'extended_hours': False, 'include_events': True, 'last_verified': None}, 'fincept_api': {'api_key': '', 'endpoint': 'https://api.fincept.com', 'real_time': True, 'enabled': False, 'last_verified': None}}, 'preferences': {'default_provider': 'yfinance', 'cache_enabled': True, 'cache_duration': 300, 'auto_verify': True}, 'created_at': datetime.now().isoformat(), 'last_modified': datetime.now().isoformat()}

